(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.RepoDiscovery=api})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const demoWords=/\b(demo|playground|live\s*(?:preview|site|app|version|example)|try\s*(?:it|online|now|the app)|launch\s*(?:app|project)|open\s*app|view\s*(?:app|project|live)|deployed\s*(?:app|site))\b/i;
function demoUrl(value){try{const u=new URL(value.replace(/&amp;/g,'&'));const host=u.hostname.toLowerCase();if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return null;if(host==='localhost'||host==='127.0.0.1'||host==='example.com'||host.endsWith('.example.com'))return null;if(/(^|\.)(github\.com|githubusercontent\.com|youtube\.com|youtu\.be|shields\.io|imgur\.com|npmjs\.com|vercel\.com|netlify\.com)$/.test(host))return null;if(/\.(png|jpe?g|gif|svg|webp|mp4|webm|pdf|zip)(?:$|\?)/i.test(u.pathname))return null;return u.href}catch{return null}}
function extractDemo(markdown,homepage){const text=String(markdown||'').replace(/```[\s\S]*?```/g,'');const refs=new Map();for(const m of text.matchAll(/^\s*\[([^\]]+)\]:\s*<?(https?:\/\/[^\s>]+)>?/gm))refs.set(m[1].toLowerCase(),m[2]);const candidates=[];
for(const m of text.matchAll(/\[([^\]\n]+)\]\(\s*<?(https?:\/\/[^\s)>]+)>?(?:\s+[^)]*)?\)/g))if(demoWords.test(m[1]))candidates.push(m[2]);
for(const m of text.matchAll(/\[!\[([^\]]+)\]\([^)]*\)\]\(<?(https?:\/\/[^\s)>]+)>?\)/g))if(demoWords.test(m[1]))candidates.push(m[2]);
for(const m of text.matchAll(/\[([^\]\n]+)\]\[([^\]]*)\]/g))if(demoWords.test(m[1]))candidates.push(refs.get((m[2]||m[1]).toLowerCase()));
for(const m of text.matchAll(/<a\b[^>]*href=["'](https?:\/\/[^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi))if(demoWords.test(m[2].replace(/<[^>]*>/g,' ')))candidates.push(m[1]);
const lines=text.split('\n');for(let i=0;i<lines.length;i++){const line=lines[i];if(!demoWords.test(line))continue;const heading=/^\s*#{1,6}\s/.test(line);const segment=heading?lines.slice(i,i+5).join('\n'):line;for(const m of segment.matchAll(/https?:\/\/[^\s<>"')\]]+/g))candidates.push(m[0].replace(/[.,;]+$/,''));}
for(const value of candidates){if(!value)continue;const url=demoUrl(value);if(url)return url;}
// A project homepage is accepted only when it is also explicitly presented as a demo.
const home=homepage&&demoUrl(homepage);return home&&candidates.some(v=>v&&demoUrl(v)===home)?home:null;}
function classify(r){const t=(r.topics||[]).join(' ')+' '+(r.description||'')+' '+(r.name||'');return /design|canvas|draw|ui-library|whiteboard|portfolio|animation|css/i.test(t)?'Design':/budget|finance|money|expense/i.test(t)?'Finance':/crm|business|ecommerce|scheduling|commerce/i.test(t)?'Business':/learn|education|typing|quiz/i.test(t)?'Education':/notes|markdown|productivity|task|resume|todo|calendar/i.test(t)?'Productivity':/developer|api|database|tool|editor|framework|code/i.test(t)?'Developer tools':'Other'}
const terms={'Design':'design OR drawing OR portfolio OR animation','Developer tools':'developer OR api OR editor OR database','Productivity':'productivity OR notes OR todo OR calendar','Business':'business OR crm OR ecommerce OR scheduling','Finance':'finance OR budget OR expense OR money','Education':'education OR learning OR quiz OR typing'};
function searchQueries({query='',category='All projects',demos=true,newest=false}={}){const common=' is:public archived:false fork:false';const recent=newest?' created:>='+new Date(Date.now()-30*86400000).toISOString().slice(0,10):'';const user=query.trim().slice(0,200);let seeds;if(user)seeds=[user+' in:name,description,readme'];else if(terms[category])seeds=[terms[category]+' in:name,description,readme'];else seeds=demos?['demo in:readme','playground in:readme','"live preview" in:readme','"live site" in:readme','topic:live-demo','"try online" in:readme']:['stars:>=1'];return seeds.map(q=>q+common+recent)}
function isAvailable(repo){return repo?.availability!=='unavailable'}
function mapRepo(d){const palette=[['#25392f','#d1e5c5'],['#323057','#d6caff'],['#193546','#a6d6e8'],['#63362a','#f8c7a8'],['#302e55','#dbd2ff']];let hash=0;for(const c of d.full_name)hash=(hash*31+c.charCodeAt(0))>>>0;const [color,ink]=palette[hash%palette.length];return {availability:d.private===true?'unavailable':'available',full:d.full_name,name:d.name,description:d.description||'Explore this public GitHub project.',category:classify(d),language:d.language,stars:d.stargazers_count,forks:d.forks_count,created:d.created_at,updated:d.pushed_at,license:d.license?.spdx_id==='NOASSERTION'?null:d.license?.spdx_id,branch:d.default_branch||'main',homepage:d.homepage,topics:d.topics||[],demo:null,color,ink}}
return {extractDemo,demoUrl,classify,searchQueries,mapRepo,isAvailable};
});
